import json,pathlib
root=pathlib.Path(__file__).resolve().parents[2]
adult=[]
for i,line in enumerate((root/'scripts/launch/adult.tsv').read_text().splitlines()):
 w,d,a,b=line.split('|'); cat='Character & habits' if i<50 else 'Work & decisions' if i<80 else 'Feelings & people' if i<100 else 'Ideas & understanding' if i<130 else 'Everyday choices' if i<165 else 'Useful actions'
 adult.append(dict(id=w,word=w,meaning=d,panels=[a,b],example=b,category=cat,art=f'assets/launch/story-{i//10:02}.webp',cells=[(i%10)*2,(i%10)*2+1],kind='comic',prompt='Describe a different real situation where this word fits.'))
pictures=[]
for i,line in enumerate((root/'scripts/launch/pictures.tsv').read_text().splitlines()):
 w,emoji,d,ex,cat=line.split('|');pictures.append(dict(id=w.replace(' ','-'),word=w,emoji=emoji,meaning=d,panels=[d,ex],example=ex,category=cat,art=f'assets/launch/pictures-{i//20:02}.webp',cells=[i%20,i%20],kind='picture',prompt='Say a new sentence about this picture.'))
ages={'4-6':{'label':'Little explorers','method':'Look, listen & say','words':pictures},'7-9':{'label':'Story scouts','method':'Picture, spell & build','words':pictures},'10-13':{'label':'Story makers','method':'Predict, remember & explain','words':pictures[100:]+adult[:100]},'14-17':{'label':'Language lab','method':'Notice, retrieve & express','words':adult},'18+':{'label':'Everyday English','method':'See it. Recall it. Use it.','words':adult}}
(root/'launch-content.js').write_text('/* Curated launch curriculum; generated by scripts/launch/build-content.py. */\nwindow.LaunchContent='+json.dumps(ages,ensure_ascii=False,separators=(',',':'))+';\n')
report={a:{'count':len(v['words']),'distinct':len(set(w['word'] for w in v['words'])),'method':v['method']} for a,v in ages.items()}
(root/'docs/LAUNCH_COVERAGE.json').write_text(json.dumps(report,indent=2));print(report)
